#!/usr/bin/env python3
import sys
import openpyxl

def main():
    spreadsheet_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb['Sheet1']

    target = '#N/A'
    max_col = ws.max_column  # N = 14

    kept_rows = []
    # Row 1 must remain blank; scan data rows from 2 to max_row
    for r in range(2, ws.max_row + 1):
        val = ws.cell(row=r, column=3).value
        if isinstance(val, str) and val == target:
            row_data = [ws.cell(row=r, column=c).value for c in range(1, max_col + 1)]
            kept_rows.append(row_data)

    # Clear the entire answer range A2:N73, leaving row 1 blank
    for r in range(2, ws.max_row + 1):
        for c in range(1, max_col + 1):
            ws.cell(row=r, column=c).value = None

    # Write kept rows compactly starting at row 2
    for i, row_data in enumerate(kept_rows, start=2):
        for c in range(1, max_col + 1):
            ws.cell(row=i, column=c).value = row_data[c - 1]

    wb.save(output_path)

if __name__ == '__main__':
    main()

