import sys
from datetime import date
from openpyxl import load_workbook

def main():
    input_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = load_workbook(input_path)
    ws = wb["Sheet1"]

    # Build holiday map: holiday_date -> type (e.g. PH(working) / PH(non-working))
    # Column A = DATE (col 1), Column E = WORKDAY (col 5),
    # Column I = holiday Date (col 9), Column J = Type (col 10)
    holiday_map = {}
    for row in range(1, ws.max_row + 1):
        hdate = ws.cell(row=row, column=9).value
        htype = ws.cell(row=row, column=10).value
        if hdate is None or htype is None:
            continue
        if isinstance(hdate, str):
            try:
                d = date.fromisoformat(str(hdate)[:10])
            except ValueError:
                continue
        else:
            # datetime or date
            d = hdate.date() if hasattr(hdate, "date") else hdate
        holiday_map[d] = str(htype)

    weekday_names = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

    # Fill E2:E75
    for row in range(2, 76):
        cell_a = ws.cell(row=row, column=1).value
        if cell_a is None:
            continue
        if isinstance(cell_a, str):
            try:
                d = date.fromisoformat(str(cell_a)[:10])
            except ValueError:
                continue
        else:
            d = cell_a.date() if hasattr(cell_a, "date") else cell_a

        if d in holiday_map:
            value = holiday_map[d]
        else:
            value = weekday_names[d.weekday()]

        ws.cell(row=row, column=5).value = value

    wb.save(output_path)

if __name__ == "__main__":
    main()

