import sys
import openpyxl

def is_whole_number(val):
    if val is None:
        return False
    try:
        num = float(val)
    except (TypeError, ValueError):
        return False
    return abs(num - round(num)) < 1e-9

def main():
    spreadsheet_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb['Sheet1']

    # Column E: Payee, Column F: amount, Column H
    for r in range(2, 18):
        payee = ws.cell(r, 5).value
        amount = ws.cell(r, 6).value
        if payee is not None and 'Georgia Its Tax' in str(payee):
            if is_whole_number(amount):
                ws.cell(r, 5).value = 'Georgia WH Tax'
            else:
                ws.cell(r, 5).value = 'Georgia Sales Tax'

    # Column H should be empty without background colour
    for r in range(2, 18):
        cell = ws.cell(r, 8)
        cell.value = None
        fill = cell.fill
        if fill and fill.fill_type is not None:
            # reset to no fill
            from openpyxl.styles import PatternFill
            cell.fill = PatternFill(fill_type=None)

    wb.save(output_path)

if __name__ == '__main__':
    main()

