import sys
from copy import copy
import openpyxl


def main():
    src = sys.argv[1]
    dst = sys.argv[2]

    wb = openpyxl.load_workbook(src)
    ws = wb['Sheet1']

    max_row = ws.max_row
    max_col = ws.max_column

    # 1. Find the header row (the row whose first data cell is 'Row Labels').
    header_row = None
    for r in range(1, max_row + 1):
        for c in range(1, max_col + 1):
            if ws.cell(row=r, column=c).value == 'Row Labels':
                header_row = r
                break
        if header_row is not None:
            break

    # 2. Locate the dynamic column labeled '0-15'.
    col_015 = None
    for c in range(1, max_col + 1):
        if ws.cell(row=header_row, column=c).value == '0-15':
            col_015 = c
            break

    old_cols = list(range(1, max_col + 1))
    # New order: keep column A, then put '0-15', then everything else in order.
    new_cols = [old_cols[0], col_015] + [c for c in old_cols[1:] if c != col_015]

    # 3. Capture all values + styles (so '0-15' carries its formatting to column B).
    values = {}
    styles = {}
    for r in range(1, max_row + 1):
        for c in old_cols:
            cell = ws.cell(row=r, column=c)
            values[(r, c)] = cell.value
            styles[(r, c)] = copy(cell._style)

    # 4. Clear the whole region.
    for r in range(1, max_row + 1):
        for c in old_cols:
            ws.cell(row=r, column=c).value = None

    # 5. Re-write in the new order ('0-15' now occupies column B, Grand Total stays in L).
    for r in range(1, max_row + 1):
        for new_pos, old_col in enumerate(new_cols, start=1):
            cell = ws.cell(row=r, column=new_pos)
            cell.value = values.get((r, old_col))
            cell._style = styles[(r, old_col)]

    wb.save(dst)


if __name__ == '__main__':
    main()

