import sys
import openpyxl
from collections import defaultdict

input_path = sys.argv[1]
output_path = sys.argv[2]

wb = openpyxl.load_workbook(input_path)
ws = wb.active

# Gather rows data keyed by MRN
groups = defaultdict(list)
max_row = ws.max_row  # 20
for r in range(2, max_row + 1):
    mrn = ws.cell(row=r, column=1).value
    if mrn is None:
        continue
    status = ws.cell(row=r, column=4).value  # D
    e_val = ws.cell(row=r, column=5).value   # E
    groups[mrn].append((r, status, e_val))


def classify(rows):
    statuses = {str(st).strip().lower() if st is not None else '' for _, st, _ in rows}
    has_ns = any('no show' in s for s in statuses)
    has_sch = any(s == 'sch' for s in statuses)
    if has_ns and has_sch:
        return 'NS/SCHED'
    if has_sch and not has_ns:
        return 'FUTURE'
    # only No Show
    if has_ns:
        # check E for no-show rows: any date present -> NO ACTION NEEDED, else CALL PT
        any_date = False
        all_empty = True
        for _, st, e_val in rows:
            if st is not None and 'no show' in str(st).strip().lower():
                if e_val is not None and str(e_val).strip() != '':
                    any_date = True
                    all_empty = False
                else:
                    all_empty = False
        if any_date:
            return 'NO ACTION NEEDED'
        else:
            return 'CALL PT'
    return None


# Write result into every cell in the group
for mrn, rows in groups.items():
    result = classify(rows)
    for r, _, _ in rows:
        ws.cell(row=r, column=6).value = result  # F

wb.save(output_path)
print("done")

