import sys
import openpyxl

def main():
    input_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(input_path)
    raw = wb['Raw Data']

    # Whole-number columns are A, C, E (1, 3, 5). Read each column top-to-bottom.
    whole_numbers = []
    for col_idx in (1, 3, 5):
        # columns taken in order A, then C, then E; each flattened in row order
        for row_idx in range(1, raw.max_row + 1):
            val = raw.cell(row=row_idx, column=col_idx).value
            if val is None:
                continue
            # treat as whole number
            if isinstance(val, float) and val.is_integer():
                val = int(val)
            whole_numbers.append(int(val))

    # Write into Numbers sheet A1:F9 (rows of up to 6 numbers each)
    target = wb['Numbers']
    # clear the target range just in case
    for r in range(1, 10):
        for c in range(1, 7):
            target.cell(row=r, column=c).value = None

    idx = 0
    for row_idx in range(1, 10):
        for col_idx in range(1, 7):
            if idx < len(whole_numbers):
                target.cell(row=row_idx, column=col_idx).value = whole_numbers[idx]
                idx += 1
            else:
                break

    wb.save(output_path)

if __name__ == '__main__':
    main()
